// Keep this former blog worker URL available so returning visitors get the portfolio.
// This replacement does not cache requests or delete any stored browser data.
self.addEventListener('install', event => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: 'window' });
    await self.registration.unregister();
    await Promise.all(windows.map(client => {
      const url = new URL(client.url);
      if (url.origin === self.location.origin && ['/', '/index.html'].includes(url.pathname)) {
        return client.navigate(client.url);
      }
    }));
  })());
});
